#!/usr/bin/env bun
/**
 * Simple utility script that validates JSON input from stdin.
 *
 * Usage:
 *   echo '{"valid": true}' | bun run src/validate-json.ts
 *   cat file.json | bun run src/validate-json.ts
 *
 * Exit codes:
 *   0 - Valid JSON
 *   1 - Invalid JSON or error
 */

/**
 * Result of JSON validation.
 */
export interface ValidationResult {
  valid: boolean;
  data?: unknown;
  error?: string;
}

/**
 * Validates a JSON string and returns the result.
 */
export function validateJson(input: string): ValidationResult {
  if (!input.trim()) {
    return {
      valid: false,
      error: "Empty input",
    };
  }

  try {
    const data = JSON.parse(input);
    return {
      valid: true,
      data,
    };
  } catch (err) {
    const errorMessage =
      err instanceof SyntaxError ? err.message : "Unknown parsing error";
    return {
      valid: false,
      error: errorMessage,
    };
  }
}

/**
 * Reads all input from stdin.
 */
async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];
  const reader = Bun.stdin.stream().getReader();

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    if (value) chunks.push(value);
  }

  const decoder = new TextDecoder();
  return chunks.map((chunk) => decoder.decode(chunk)).join("");
}

/**
 * Main entry point for CLI usage.
 */
async function main(): Promise<void> {
  const input = await readStdin();
  const result = validateJson(input);

  if (result.valid) {
    console.log("Valid JSON");
    console.log(JSON.stringify(result.data, null, 2));
    process.exit(0);
  } else {
    console.error("Invalid JSON:", result.error);
    process.exit(1);
  }
}

// Run main when executed directly
main();

import { describe, expect, test } from "bun:test";
import { validateJson, type ValidationResult } from "./validate-json";

describe("validateJson", () => {
  test("returns valid for well-formed JSON object", () => {
    const result = validateJson('{"name": "test", "value": 123}');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ name: "test", value: 123 });
    expect(result.error).toBeUndefined();
  });

  test("returns valid for JSON array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3]);
  });

  test("returns valid for JSON primitives", () => {
    expect(validateJson('"hello"').valid).toBe(true);
    expect(validateJson("42").valid).toBe(true);
    expect(validateJson("true").valid).toBe(true);
    expect(validateJson("null").valid).toBe(true);
  });

  test("returns invalid for malformed JSON", () => {
    const result = validateJson("{invalid json}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
    expect(result.data).toBeUndefined();
  });

  test("returns invalid for empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("returns invalid for whitespace-only input", () => {
    const result = validateJson("   \n\t  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("returns invalid for trailing comma", () => {
    const result = validateJson('{"a": 1,}');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid for single quotes", () => {
    const result = validateJson("{'key': 'value'}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

