        "file_path": "/private/tmp/rp1-evals/8ff8cb74/workspace/src/json-validator.ts",
        "content": "/**\n * Ultra performant JSON validation module.\n *\n * Design principles for performance:\n * - Fail fast: Return on first error\n * - Minimal allocations: Reuse validators\n * - Type guards: Enable JIT optimization\n * - No external dependencies: Zero overhead\n */\n\n/**\n * Supported JSON schema types for validation.\n */\nexport type JsonSchemaType =\n  | \"string\"\n  | \"number\"\n  | \"boolean\"\n  | \"null\"\n  | \"array\"\n  | \"object\";\n\n/**\n * JSON Schema definition for validation.\n */\nexport interface JsonSchema {\n  type: JsonSchemaType | JsonSchemaType[];\n  properties?: Record<string, JsonSchema>;\n  items?: JsonSchema;\n  required?: string[];\n  minLength?: number;\n  maxLength?: number;\n  minimum?: number;\n  maximum?: number;\n  pattern?: string;\n  enum?: unknown[];\n}\n\n/**\n * Validation result with error details.\n */\nexport interface ValidationResult {\n  valid: boolean;\n  errors: ValidationError[];\n}\n\n/**\n * Validation error with path and message.\n */\nexport interface ValidationError {\n  path: string;\n  message: string;\n  value?: unknown;\n}\n\n/**\n * Pre-compiled validator for maximum performance.\n * Compile once, validate many times.\n */\nexport interface CompiledValidator {\n  validate: (data: unknown) => ValidationResult;\n  schema: JsonSchema;\n}\n\n/**\n * Fast type check using typeof and Array.isArray.\n * Inlined for JIT optimization.\n */\nfunction getJsonType(value: unknown): JsonSchemaType | \"undefined\" {\n  if (value === null) return \"null\";\n  if (Array.isArray(value)) return \"array\";\n  const t = typeof value;\n  if (t === \"string\" || t === \"number\" || t === \"boolean\" || t === \"object\") {\n    return t as JsonSchemaType;\n  }\n  return \"undefined\";\n}\n\n/**\n * Check if value matches expected type(s).\n */\nfunction matchesType(\n  value: unknown,\n  expectedType: JsonSchemaType | JsonSchemaType[]\n): boolean {\n  const actualType = getJsonType(value);\n  if (Array.isArray(expectedType)) {\n    return expectedType.includes(actualType as JsonSchemaType);\n  }\n  return actualType === expectedType;\n}\n\n/**\n * Validate a value against a schema.\n * Returns errors array - empty if valid.\n *\n * @internal\n */\nfunction validateValue(\n  value: unknown,\n  schema: JsonSchema,\n  path: string,\n  errors: ValidationError[],\n  failFast: boolean\n): boolean {\n  // Type check\n  if (!matchesType(value, schema.type)) {\n    errors.push({\n      path,\n      message: `Expected type ${JSON.stringify(schema.type)}, got ${getJsonType(value)}`,\n      value,\n    });\n    if (failFast) return false;\n  }\n\n  // Enum check\n  if (schema.enum !== undefined) {\n    if (!schema.enum.some((e) => JSON.stringify(e) === JSON.stringify(value))) {\n      errors.push({\n        path,\n        message: `Value must be one of: ${JSON.stringify(schema.enum)}`,\n        value,\n      });\n      if (failFast) return false;\n    }\n  }\n\n  // String validations\n  if (typeof value === \"string\") {\n    if (schema.minLength !== undefined && value.length < schema.minLength) {\n      errors.push({\n        path,\n        message: `String length ${value.length} is less than minimum ${schema.minLength}`,\n        value,\n      });\n      if (failFast) return false;\n    }\n    if (schema.maxLength !== undefined && value.length > schema.maxLength) {\n      errors.push({\n        path,\n        message: `String length ${value.length} exceeds maximum ${schema.maxLength}`,\n        value,\n      });\n      if (failFast) return false;\n    }\n    if (schema.pattern !== undefined) {\n      const regex = new RegExp(schema.pattern);\n      if (!regex.test(value)) {\n        errors.push({\n          path,\n          message: `String does not match pattern: ${schema.pattern}`,\n          value,\n        });\n        if (failFast) return false;\n      }\n    }\n  }\n\n  // Number validations\n  if (typeof value === \"number\") {\n    if (schema.minimum !== undefined && value < schema.minimum) {\n      errors.push({\n        path,\n        message: `Number ${value} is less than minimum ${schema.minimum}`,\n        value,\n      });\n      if (failFast) return false;\n    }\n    if (schema.maximum !== undefined && value > schema.maximum) {\n      errors.push({\n        path,\n        message: `Number ${value} exceeds maximum ${schema.maximum}`,\n        value,\n      });\n      if (failFast) return false;\n    }\n  }\n\n  // Array validations\n  if (Array.isArray(value) && schema.items) {\n    for (let i = 0; i < value.length; i++) {\n      const itemPath = `${path}[${i}]`;\n      const valid = validateValue(\n        value[i],\n        schema.items,\n        itemPath,\n        errors,\n        failFast\n      );\n      if (!valid && failFast) return false;\n    }\n  }\n\n  // Object validations\n  if (\n    typeof value === \"object\" &&\n    value !== null &&\n    !Array.isArray(value) &&\n    schema.properties\n  ) {\n    const obj = value as Record<string, unknown>;\n\n    // Required fields check\n    if (schema.required) {\n      for (const key of schema.required) {\n        if (!(key in obj)) {\n          errors.push({\n            path: path ? `${path}.${key}` : key,\n            message: `Missing required property: ${key}`,\n          });\n          if (failFast) return false;\n        }\n      }\n    }\n\n    // Property validations\n    for (const [key, propSchema] of Object.entries(schema.properties)) {\n      if (key in obj) {\n        const propPath = path ? `${path}.${key}` : key;\n        const valid = validateValue(\n          obj[key],\n          propSchema,\n          propPath,\n          errors,\n          failFast\n        );\n        if (!valid && failFast) return false;\n      }\n    }\n  }\n\n  return errors.length === 0;\n}\n\n/**\n * Compile a schema into a reusable validator.\n * Pre-compilation enables maximum validation speed.\n *\n * @param schema - JSON Schema to compile\n * @returns Compiled validator with validate function\n *\n * @example\n * const validator = compileSchema({\n *   type: \"object\",\n *   properties: { name: { type: \"string\" } },\n *   required: [\"name\"]\n * });\n * const result = validator.validate({ name: \"test\" });\n */\nexport function compileSchema(schema: JsonSchema): CompiledValidator {\n  return {\n    schema,\n    validate: (data: unknown): ValidationResult => {\n      const errors: ValidationError[] = [];\n      validateValue(data, schema, \"\", errors, true);\n      return { valid: errors.length === 0, errors };\n    },\n  };\n}\n\n/**\n * Validate JSON data against a schema.\n * For one-off validation - use compileSchema for repeated validation.\n *\n * @param data - Data to validate\n * @param schema - JSON Schema to validate against\n * @returns Validation result with errors\n *\n * @example\n * const result = validateJson({ name: \"test\" }, { type: \"object\" });\n * if (!result.valid) console.error(result.errors);\n */\nexport function validateJson(data: unknown, schema: JsonSchema): ValidationResult {\n  const errors: ValidationError[] = [];\n  validateValue(data, schema, \"\", errors, true);\n  return { valid: errors.length === 0, errors };\n}\n\n/**\n * Validate JSON data and collect all errors (not fail-fast).\n * Slower but provides complete error report.\n *\n * @param data - Data to validate\n * @param schema - JSON Schema to validate against\n * @returns Validation result with all errors\n */\nexport function validateJsonFull(\n  data: unknown,\n  schema: JsonSchema\n): ValidationResult {\n  const errors: ValidationError[] = [];\n  validateValue(data, schema, \"\", errors, false);\n  return { valid: errors.length === 0, errors };\n}\n\n/**\n * Parse and validate JSON string in one operation.\n * Catches parse errors and returns as validation error.\n *\n * @param jsonString - JSON string to parse and validate\n * @param schema - JSON Schema to validate against\n * @returns Validation result\n */\nexport function parseAndValidate(\n  jsonString: string,\n  schema: JsonSchema\n): ValidationResult {\n  let data: unknown;\n  try {\n    data = JSON.parse(jsonString);\n  } catch (e) {\n    return {\n      valid: false,\n      errors: [\n        {\n          path: \"\",\n          message: `Invalid JSON: ${e instanceof Error ? e.message : String(e)}`,\n        },\n      ],\n    };\n  }\n  return validateJson(data, schema);\n}\n\n/**\n * Quick type guard check without full validation.\n * Maximum performance for simple type checks.\n *\n * @param data - Data to check\n * @param type - Expected type\n * @returns True if data matches type\n */\nexport function isType(\n  data: unknown,\n  type: JsonSchemaType | JsonSchemaType[]\n): boolean {\n  return matchesType(data, type);\n}\n\n/**\n * Validate JSON file from path.\n * Reads file and validates in one operation.\n *\n * @param filePath - Path to JSON file\n * @param schema - JSON Schema to validate against\n * @returns Promise resolving to validation result\n */\nexport async function validateJsonFile(\n  filePath: string,\n  schema: JsonSchema\n): Promise<ValidationResult> {\n  try {\n    const file = Bun.file(filePath);\n    const content = await file.text();\n    return parseAndValidate(content, schema);\n  } catch (e) {\n    return {\n      valid: false,\n      errors: [\n        {\n          path: \"\",\n          message: `Failed to read file: ${e instanceof Error ? e.message : String(e)}`,\n        },\n      ],\n    };\n  }\n}\n"
