        "file_path": "/private/tmp/rp1-evals/8ff8cb74/workspace/src/json-validator.test.ts",
        "content": "import { describe, expect, test } from \"bun:test\";\nimport {\n  validateJson,\n  validateJsonFull,\n  parseAndValidate,\n  compileSchema,\n  isType,\n  type JsonSchema,\n} from \"./json-validator\";\n\ndescribe(\"json-validator\", () => {\n  describe(\"validateJson\", () => {\n    test(\"validates string type\", () => {\n      const schema: JsonSchema = { type: \"string\" };\n      expect(validateJson(\"hello\", schema).valid).toBe(true);\n      expect(validateJson(123, schema).valid).toBe(false);\n    });\n\n    test(\"validates number type\", () => {\n      const schema: JsonSchema = { type: \"number\" };\n      expect(validateJson(42, schema).valid).toBe(true);\n      expect(validateJson(\"42\", schema).valid).toBe(false);\n    });\n\n    test(\"validates boolean type\", () => {\n      const schema: JsonSchema = { type: \"boolean\" };\n      expect(validateJson(true, schema).valid).toBe(true);\n      expect(validateJson(false, schema).valid).toBe(true);\n      expect(validateJson(\"true\", schema).valid).toBe(false);\n    });\n\n    test(\"validates null type\", () => {\n      const schema: JsonSchema = { type: \"null\" };\n      expect(validateJson(null, schema).valid).toBe(true);\n      expect(validateJson(undefined, schema).valid).toBe(false);\n    });\n\n    test(\"validates array type\", () => {\n      const schema: JsonSchema = { type: \"array\" };\n      expect(validateJson([], schema).valid).toBe(true);\n      expect(validateJson([1, 2, 3], schema).valid).toBe(true);\n      expect(validateJson({}, schema).valid).toBe(false);\n    });\n\n    test(\"validates object type\", () => {\n      const schema: JsonSchema = { type: \"object\" };\n      expect(validateJson({}, schema).valid).toBe(true);\n      expect(validateJson({ a: 1 }, schema).valid).toBe(true);\n      expect(validateJson([], schema).valid).toBe(false);\n    });\n\n    test(\"validates union types\", () => {\n      const schema: JsonSchema = { type: [\"string\", \"number\"] };\n      expect(validateJson(\"hello\", schema).valid).toBe(true);\n      expect(validateJson(42, schema).valid).toBe(true);\n      expect(validateJson(true, schema).valid).toBe(false);\n    });\n\n    test(\"validates string minLength\", () => {\n      const schema: JsonSchema = { type: \"string\", minLength: 3 };\n      expect(validateJson(\"abc\", schema).valid).toBe(true);\n      expect(validateJson(\"ab\", schema).valid).toBe(false);\n    });\n\n    test(\"validates string maxLength\", () => {\n      const schema: JsonSchema = { type: \"string\", maxLength: 5 };\n      expect(validateJson(\"hello\", schema).valid).toBe(true);\n      expect(validateJson(\"hello!\", schema).valid).toBe(false);\n    });\n\n    test(\"validates string pattern\", () => {\n      const schema: JsonSchema = { type: \"string\", pattern: \"^[a-z]+$\" };\n      expect(validateJson(\"abc\", schema).valid).toBe(true);\n      expect(validateJson(\"ABC\", schema).valid).toBe(false);\n    });\n\n    test(\"validates number minimum\", () => {\n      const schema: JsonSchema = { type: \"number\", minimum: 0 };\n      expect(validateJson(0, schema).valid).toBe(true);\n      expect(validateJson(10, schema).valid).toBe(true);\n      expect(validateJson(-1, schema).valid).toBe(false);\n    });\n\n    test(\"validates number maximum\", () => {\n      const schema: JsonSchema = { type: \"number\", maximum: 100 };\n      expect(validateJson(100, schema).valid).toBe(true);\n      expect(validateJson(50, schema).valid).toBe(true);\n      expect(validateJson(101, schema).valid).toBe(false);\n    });\n\n    test(\"validates enum values\", () => {\n      const schema: JsonSchema = { type: \"string\", enum: [\"red\", \"green\", \"blue\"] };\n      expect(validateJson(\"red\", schema).valid).toBe(true);\n      expect(validateJson(\"yellow\", schema).valid).toBe(false);\n    });\n\n    test(\"validates required properties\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          name: { type: \"string\" },\n          age: { type: \"number\" },\n        },\n        required: [\"name\"],\n      };\n      expect(validateJson({ name: \"John\" }, schema).valid).toBe(true);\n      expect(validateJson({ age: 30 }, schema).valid).toBe(false);\n    });\n\n    test(\"validates nested objects\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          user: {\n            type: \"object\",\n            properties: {\n              name: { type: \"string\" },\n            },\n            required: [\"name\"],\n          },\n        },\n        required: [\"user\"],\n      };\n      expect(validateJson({ user: { name: \"John\" } }, schema).valid).toBe(true);\n      expect(validateJson({ user: {} }, schema).valid).toBe(false);\n    });\n\n    test(\"validates array items\", () => {\n      const schema: JsonSchema = {\n        type: \"array\",\n        items: { type: \"number\" },\n      };\n      expect(validateJson([1, 2, 3], schema).valid).toBe(true);\n      expect(validateJson([1, \"2\", 3], schema).valid).toBe(false);\n    });\n\n    test(\"fails fast on first error\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          a: { type: \"string\" },\n          b: { type: \"string\" },\n          c: { type: \"string\" },\n        },\n      };\n      const result = validateJson({ a: 1, b: 2, c: 3 }, schema);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBe(1);\n    });\n  });\n\n  describe(\"validateJsonFull\", () => {\n    test(\"collects all errors\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          a: { type: \"string\" },\n          b: { type: \"string\" },\n          c: { type: \"string\" },\n        },\n      };\n      const result = validateJsonFull({ a: 1, b: 2, c: 3 }, schema);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBe(3);\n    });\n  });\n\n  describe(\"parseAndValidate\", () => {\n    test(\"parses and validates valid JSON\", () => {\n      const schema: JsonSchema = { type: \"object\" };\n      const result = parseAndValidate('{\"name\":\"test\"}', schema);\n      expect(result.valid).toBe(true);\n    });\n\n    test(\"returns error for invalid JSON syntax\", () => {\n      const schema: JsonSchema = { type: \"object\" };\n      const result = parseAndValidate(\"{invalid}\", schema);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"Invalid JSON\");\n    });\n\n    test(\"returns validation error for valid JSON but wrong schema\", () => {\n      const schema: JsonSchema = { type: \"array\" };\n      const result = parseAndValidate('{\"name\":\"test\"}', schema);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].message).toContain(\"Expected type\");\n    });\n  });\n\n  describe(\"compileSchema\", () => {\n    test(\"returns reusable validator\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: { id: { type: \"number\" } },\n        required: [\"id\"],\n      };\n      const validator = compileSchema(schema);\n\n      expect(validator.validate({ id: 1 }).valid).toBe(true);\n      expect(validator.validate({ id: 2 }).valid).toBe(true);\n      expect(validator.validate({}).valid).toBe(false);\n    });\n\n    test(\"preserves schema reference\", () => {\n      const schema: JsonSchema = { type: \"string\" };\n      const validator = compileSchema(schema);\n      expect(validator.schema).toBe(schema);\n    });\n  });\n\n  describe(\"isType\", () => {\n    test(\"checks single type\", () => {\n      expect(isType(\"hello\", \"string\")).toBe(true);\n      expect(isType(42, \"number\")).toBe(true);\n      expect(isType(true, \"boolean\")).toBe(true);\n      expect(isType(null, \"null\")).toBe(true);\n      expect(isType([], \"array\")).toBe(true);\n      expect(isType({}, \"object\")).toBe(true);\n    });\n\n    test(\"checks union types\", () => {\n      expect(isType(\"hello\", [\"string\", \"number\"])).toBe(true);\n      expect(isType(42, [\"string\", \"number\"])).toBe(true);\n      expect(isType(true, [\"string\", \"number\"])).toBe(false);\n    });\n  });\n\n  describe(\"error messages\", () => {\n    test(\"includes path for nested errors\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: {\n          user: {\n            type: \"object\",\n            properties: {\n              name: { type: \"string\" },\n            },\n          },\n        },\n      };\n      const result = validateJson({ user: { name: 123 } }, schema);\n      expect(result.errors[0].path).toBe(\"user.name\");\n    });\n\n    test(\"includes array index in path\", () => {\n      const schema: JsonSchema = {\n        type: \"array\",\n        items: { type: \"string\" },\n      };\n      const result = validateJson([\"a\", \"b\", 3], schema);\n      expect(result.errors[0].path).toBe(\"[2]\");\n    });\n\n    test(\"includes value in error\", () => {\n      const schema: JsonSchema = { type: \"string\" };\n      const result = validateJson(42, schema);\n      expect(result.errors[0].value).toBe(42);\n    });\n  });\n\n  describe(\"performance characteristics\", () => {\n    test(\"handles large arrays efficiently\", () => {\n      const schema: JsonSchema = {\n        type: \"array\",\n        items: { type: \"number\" },\n      };\n      const largeArray = Array.from({ length: 10000 }, (_, i) => i);\n\n      const start = performance.now();\n      const result = validateJson(largeArray, schema);\n      const elapsed = performance.now() - start;\n\n      expect(result.valid).toBe(true);\n      expect(elapsed).toBeLessThan(100); // Should complete in under 100ms\n    });\n\n    test(\"compiled validator is reusable\", () => {\n      const schema: JsonSchema = {\n        type: \"object\",\n        properties: { id: { type: \"number\" } },\n      };\n      const validator = compileSchema(schema);\n\n      const start = performance.now();\n      for (let i = 0; i < 10000; i++) {\n        validator.validate({ id: i });\n      }\n      const elapsed = performance.now() - start;\n\n      expect(elapsed).toBeLessThan(100); // 10k validations under 100ms\n    });\n  });\n});\n"
